function jdFromDate(dd,mm,yy){let a=Math.floor((14-mm)/12),y=yy+4800-a,m=mm+12*a-3;let jd=dd+Math.floor((153*m+2)/5)+365*y+Math.floor(y/4)-Math.floor(y/100)+Math.floor(y/400)-32045;if(jd<2299161)jd=dd+Math.floor((153*m+2)/5)+365*y+Math.floor(y/4)-32083;return jd}
function newMoon(k){let T=k/1236.85,T2=T*T,T3=T2*T,dr=Math.PI/180,Jd1=2415020.75933+29.53058868*k+0.0001178*T2-0.000000155*T3;Jd1+=0.00033*Math.sin((166.56+132.87*T-0.009173*T2)*dr);let M=359.2242+29.10535608*k-0.0000333*T2-0.00000347*T3,Mp=306.0253+385.81691806*k+0.0107306*T2+0.00001236*T3,F=21.2964+390.67050646*k-0.0016528*T2-0.00000239*T3,C1=(0.1734-0.000393*T)*Math.sin(M*dr)+0.0021*Math.sin(2*M*dr)-0.4068*Math.sin(Mp*dr)+0.0161*Math.sin(2*Mp*dr)-0.0004*Math.sin(3*Mp*dr)+0.0104*Math.sin(2*F*dr)-0.0051*Math.sin((M+Mp)*dr)-0.0074*Math.sin((M-Mp)*dr)+0.0004*Math.sin((2*F+M)*dr)-0.0004*Math.sin((2*F-M)*dr)-0.0006*Math.sin((2*F+Mp)*dr)+0.0010*Math.sin((2*F-Mp)*dr)+0.0005*Math.sin((2*Mp+M)*dr),deltat=T< -11?0.001+0.000839*T+0.0002261*T2-0.00000845*T3-0.000000081*T*T3:-0.000278+0.000265*T+0.000262*T2;return Jd1+C1-deltat}
function newMoonDay(k){return Math.floor(newMoon(k)+0.5+7/24)}
function sunLongitude(jdn){let T=(jdn-2451545.5-7/24)/36525,T2=T*T,dr=Math.PI/180,M=357.52910+35999.05030*T-0.0001559*T2-0.00000048*T*T2,L0=280.46645+36000.76983*T+0.0003032*T2,DL=(1.914600-0.004817*T-0.000014*T2)*Math.sin(dr*M)+(0.019993-0.000101*T)*Math.sin(2*dr*M)+0.000290*Math.sin(3*dr*M),L=(L0+DL)*dr;L-=Math.PI*2*Math.floor(L/(Math.PI*2));return Math.floor(L/Math.PI*6)}
function month11(y){let off=jdFromDate(31,12,y)-2415021,k=Math.floor(off/29.530588853),nm=newMoonDay(k);if(sunLongitude(nm)>=9)nm=newMoonDay(k-1);return nm}
function leapOffset(a11){let k=Math.floor((a11-2415021.076998695)/29.530588853+0.5),last=0,i=1,arc=sunLongitude(newMoonDay(k+i));do{last=arc;i++;arc=sunLongitude(newMoonDay(k+i))}while(arc!==last&&i<15);return i-1}
function solarToLunar(d,m,y){let day=jdFromDate(d,m,y),k=Math.floor((day-2415021.076998695)/29.530588853),start=newMoonDay(k+1);if(start>day)start=newMoonDay(k);let a11=month11(y),b11=a11,lunarYear;if(a11>=start){lunarYear=y;a11=month11(y-1)}else{lunarYear=y+1;b11=month11(y+1)}let lunarDay=day-start+1,diff=Math.floor((start-a11)/29),lunarMonth=diff+11,lunarLeap=0;if(b11-a11>365){let leap=leapOffset(a11);if(diff>=leap)lunarMonth=diff+10;if(diff===leap)lunarLeap=1}if(lunarMonth>12)lunarMonth-=12;if(lunarMonth>=11&&diff<4)lunarYear--;return{day:lunarDay,month:lunarMonth,year:lunarYear,leap:lunarLeap}}
function solarDate(y,m,d){return new Date(y,m-1,d,12)}
function eventName(day){return day===1?'Mồng một':'Ngày rằm'}
function lunarLabel(l){return l.day+' tháng '+l.month+(l.leap?' nhuận':'')+' âm lịch'}
function escapeHtml(s){return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]))}
async function api(path,opts={}){let r=await fetch(API+path,{credentials:'same-origin',...opts});if(!r.ok){let msg='Có lỗi xảy ra';try{msg=(await r.json()).error||msg}catch{}throw new Error(msg)}return r}
function initSelectors(){for(let m=1;m<=12;m++)$('monthSelect').add(new Option(new Intl.DateTimeFormat('vi-VN',{month:'long'}).format(new Date(2024,m-1,1)),m));for(let y=1900;y<=2199;y++)$('yearSelect').add(new Option(y,y));$('monthSelect').value=viewMonth;$('yearSelect').value=viewYear}
function dateIso(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function renderCalendar(){let first=solarDate(viewYear,viewMonth,1),start=(first.getDay()+6)%7,gridStart=new Date(viewYear,viewMonth-1,1-start,12);$('monthTitle').textContent=new Intl.DateTimeFormat('vi-VN',{month:'long',year:'numeric'}).format(first);let html='';for(let i=0;i<42;i++){let d=new Date(gridStart);d.setDate(gridStart.getDate()+i);let l=solarToLunar(d.getDate(),d.getMonth()+1,d.getFullYear()),isEvent=l.day===1||l.day===15,iso=dateIso(d),sel=selected&&selected.iso===iso;html+='<button class="day '+(d.getMonth()+1!==viewMonth?'out ':'')+(sel?'selected ':'')+(isToday(d)?'today':'')+'" data-date="'+iso+'"><div class="solar">'+d.getDate()+'</div><div class="lunar">'+(l.day===1?'M1':l.day+'/'+l.month+(l.leap?'N':''))+'</div>'+(isEvent?'<span class="event-mark '+(l.day===15?'full':'')+'">'+(l.day===1?'Mồng một':'Ngày rằm')+(l.leap?' · nhuận':'')+'</span>':'')+'</button>'} $('calendarGrid').innerHTML=html;document.querySelectorAll('.day[data-date]').forEach(b=>b.onclick=()=>selectDate(b.dataset.date));renderUpcoming()}
function isToday(d){return d.toDateString()===now.toDateString()}
function setMonth(y,m){viewYear=y;viewMonth=m;$('monthSelect').value=m;$('yearSelect').value=y;renderCalendar()}
function findEvents(days=45){let out=[];for(let i=0;i<=days;i++){let d=new Date(now);d.setDate(now.getDate()+i);let l=solarToLunar(d.getDate(),d.getMonth()+1,d.getFullYear());if(l.day===1||l.day===15)out.push({date:d,lunar:l,iso:dateIso(d)})}return out}
function eventRow(e,featured){let weekday=e.date.getDay(),weekdayLabel=weekday===0?'Chủ nhật':'Thứ '+(weekday+1);return '<div class="event-row '+(featured?'featured':'')+'" data-upcoming="'+e.iso+'"><div class="date-box"><small>'+weekdayLabel+'</small><span class="solar-day">'+e.date.getDate()+'</span><small>'+new Intl.DateTimeFormat('vi-VN',{month:'short'}).format(e.date)+'</small></div><div class="event-info">'+(featured?'<span class="next-label">Sắp tới gần nhất</span>':'')+'<strong>'+eventName(e.lunar.day)+(e.lunar.leap?' · tháng nhuận':'')+'</strong><small class="solar-detail">'+new Intl.DateTimeFormat('vi-VN',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Ho_Chi_Minh'}).format(e.date)+'</small><small>Tháng '+e.lunar.month+' · năm '+e.lunar.year+' âm lịch</small></div><button type="button" class="primary event-create" data-create="'+e.iso+'">Tạo poster</button></div>'}
function renderUpcoming(){let list=findEvents();$('upcomingList').innerHTML=list.slice(0,5).map((e,i)=>eventRow(e,i===0)).join('')||'<div class="empty"><b>Chưa có sự kiện sắp tới</b></div>';document.querySelectorAll('[data-upcoming]').forEach(x=>x.onclick=()=>selectEvent(x.dataset.upcoming));document.querySelectorAll('[data-create]').forEach(x=>x.onclick=ev=>{ev.stopPropagation();selectEvent(x.dataset.create)})}
function renderSelected(){let node=$('selectedEvent');if(!selected){node.innerHTML='<span class="muted">Chọn ngày mồng một hoặc ngày rằm để tạo poster.</span>';return}let l=selected.lunar;node.innerHTML='<strong>'+new Intl.DateTimeFormat('vi-VN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(selected.date)+'</strong><div class="muted" style="margin-top:5px">'+lunarLabel(l)+(l.leap?' · tháng nhuận':'')+'</div>'+(l.day===1||l.day===15?'<button class="primary" id="selectedCreate" style="margin-top:12px">Tạo poster</button>':'<div class="muted" style="margin-top:10px">Ngày thường · chọn mồng một hoặc ngày rằm.</div>');if($('selectedCreate'))$('selectedCreate').onclick=()=>openPosterEditor()}
function selectDate(iso){let parts=iso.split('-').map(Number),d=solarDate(parts[0],parts[1],parts[2]),l=solarToLunar(d.getDate(),d.getMonth()+1,d.getFullYear());selected={iso:iso,date:d,lunar:l};renderCalendar();renderSelected();if(l.day===1||l.day===15){openPosterEditor()}else{switchView('month');toast('Ngày này không phải mồng một hoặc ngày rằm.')}}
function selectEvent(iso){selectDate(iso)}
function defaultTimeFor(d){let m=d.getMonth()+1,winter=[10,11,12,1,2,3].includes(m);return{time:winter?'11:30':'17:30',label:winter?'Mùa đông · 11:30':'Mùa hè · 17:30'}}
function openPosterEditor(){if(!selected||![1,15].includes(selected.lunar.day))return;$('posterEditor').classList.remove('hide');$('posterTitle').value='Phóng sinh trong suốt Huế';let lunar=selected.lunar;$('posterDate').value=eventGregorianDate(selected.date)+' · '+(lunar.day===1?'Mồng một':'Ngày rằm')+' tháng '+lunar.month+(lunar.leap?' nhuận':'')+' âm lịch';let preset=defaultTimeFor(selected.date);$('posterTime').value=preset.time;$('seasonDefault').textContent=preset.label+' · có thể chỉnh';switchView('calendar');renderPoster();$('posterEditor').scrollIntoView({behavior:'smooth',block:'start'})}
function switchView(v){['calendar','month','backgrounds'].forEach(x=>$('view-'+x).classList.toggle('hide',x!==v));document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.view===v));if(v==='backgrounds')renderBackgroundManager()}
function bgFor(slot){return backgrounds.find(x=>x.slot===slot)}
function bgUrl(slot){let b=bgFor(slot);return API+'/backgrounds/'+slot+(b?'?v='+encodeURIComponent(b.updated_at):'')}
