function renderThemePicker(){let node=$('themePicker');if(!node)return;node.innerHTML=Object.entries(POSTER_THEMES).map(([id,t])=>'<button type="button" class="theme-choice" data-theme="'+id+'" aria-pressed="'+(id===activeTheme)+'"><span class="theme-sample" style="--sample-bg:'+t.sample[0]+';--sample-ink:'+t.sample[1]+';--sample-accent:'+t.sample[2]+'"><i></i></span><span><strong>'+t.name+'</strong><small>'+t.description+'</small></span></button>').join('');node.querySelectorAll('[data-theme]').forEach(button=>button.onclick=()=>{activeTheme=button.dataset.theme;renderThemePicker();renderPoster()})}
function renderBackgroundManager(){let node=$('backgroundManager');let html='';for(let slot=1;slot<=3;slot++){let b=bgFor(slot);html+='<article class="background-card"><h3>Background '+slot+'</h3>'+(b?'<img src="'+bgUrl(slot)+'" alt="Background '+slot+'"><p>'+escapeHtml(b.original_name)+' · '+sizeLabel(b.size_bytes)+'</p>':'<div class="missing-bg">Chưa có background.<br>Tải một ảnh để bắt đầu.</div><p>Hỗ trợ PNG, JPG hoặc WebP.</p>')+(isAdmin?'<input type="file" accept="image/png,image/jpeg,image/webp" data-bg-upload="'+slot+'" aria-label="Tải background '+slot+'"><button type="button" class="tiny" data-bg-replace="'+slot+'">'+(b?'Thay background':'Chọn ảnh')+'</button>':'<p>Đăng nhập tài khoản quản trị để thay ảnh nền.</p>')+'</article>'}node.innerHTML=html;document.querySelectorAll('[data-bg-upload]').forEach(input=>input.onchange=()=>uploadBackground(Number(input.dataset.bgUpload),input.files&&input.files[0]));document.querySelectorAll('[data-bg-replace]').forEach(btn=>btn.onclick=()=>node.querySelector('[data-bg-upload="'+btn.dataset.bgReplace+'"]').click())}
async function loadBackgrounds(){try{let r=await api('/backgrounds');backgrounds=await r.json();if(!activeSlot||!bgFor(activeSlot)){let first=backgrounds[0];activeSlot=first?first.slot:0}renderBackgroundPicker();renderBackgroundManager();renderPoster()}catch(e){toast(e.message)}}
async function uploadBackground(slot,file){if(!file)return;if(!isAdmin){toast('Chỉ quản trị viên được tải background.');return}let fd=new FormData;fd.append('slot',String(slot));fd.append('file',file);try{await api('/backgrounds',{method:'POST',body:fd});toast('Đã lưu background '+slot+'.');await loadBackgrounds()}catch(e){toast(e.message)}}
async function refreshAuth(){try{let r=await api('/session'),s=await r.json();isSignedIn=s.authenticated;isAdmin=s.admin;$('authState').innerHTML='<i class="avatar"></i>'+(s.admin?'Quản trị viên':s.authenticated?'Đã đăng nhập':'Chưa đăng nhập');$('signIn').classList.toggle('hide',s.authenticated);$('claimAdmin').classList.toggle('hide',!s.can_claim);return s}catch(e){$('authState').textContent='Chế độ xem';return{authenticated:false,admin:false}}}
function sizeLabel(n){return n<1024?n+' B':n<1048576?Math.round(n/1024)+' KB':(n/1048576).toFixed(1)+' MB'}
function toast(s){let t=$('toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}
function wrapLines(text,maxWidth,font){let ctx=$('posterCanvas').getContext('2d');ctx.font=font;let words=String(text||'').trim().split(' ').filter(Boolean),lines=[],line='';for(let word of words){let test=line?line+' '+word:word;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=word}else line=test}if(line)lines.push(line);return lines}
function roundedRect(ctx,x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath()}
async function loadBackgroundImage(slot){let b=bgFor(slot);if(!b)return null;let key=slot+':'+b.updated_at;if(bgCache.has(key))return bgCache.get(key);let img=new Image;img.src=bgUrl(slot);try{await img.decode();bgCache.set(key,img);return img}catch{return null}}
function posterFont(style,size=style.size){return (style.italic?'italic ':'')+(style.weight||400)+' '+size+'px '+style.family}
function resolvedColor(theme,token){return theme.colors[token]||token}
let posterFontsPromise=null;
function ensurePosterFonts(){if(!document.fonts)return Promise.resolve();if(!posterFontsPromise)posterFontsPromise=Promise.all([document.fonts.load('500 24px \"Be Vietnam Pro\"'),document.fonts.load('700 80px \"Noto Serif\"')]).then(()=>document.fonts.ready).catch(()=>null);return posterFontsPromise}
function fittedPosterBlock(ctx,text,zone,style,theme,maxLines=2,preferredLines=null){let value=String(text||'').normalize('NFC').trim();if(!value)return;let size=style.size,lines=[];for(;size>=14;size--){ctx.font=posterFont(style,size);lines=preferredLines?preferredLines.map(x=>String(x).normalize('NFC')):wrapLines(value,zone.width,posterFont(style,size));let widest=Math.max(0,...lines.map(line=>ctx.measureText(line).width+(style.spacing||0)*Math.max(0,Array.from(line).length-1)));if(lines.length<=maxLines&&widest<=zone.width)break}if(lines.length>maxLines)lines=lines.slice(0,maxLines);let ctxAlign=zone.align||'center',anchor=zone.x;ctx.save();ctx.textAlign=ctxAlign;ctx.textBaseline='alphabetic';ctx.font=posterFont(style,size);ctx.fillStyle=resolvedColor(theme,style.color);ctx.globalAlpha=style.opacity??theme.effects.opacity??1;ctx.shadowColor=theme.effects.shadowColor||'transparent';ctx.shadowBlur=theme.effects.shadowBlur||0;ctx.shadowOffsetX=0;ctx.shadowOffsetY=theme.effects.shadowOffsetY||0;if('letterSpacing' in ctx)ctx.letterSpacing=(style.spacing||0)+'px';let lineHeight=style.lineHeight||size*1.22;for(let row=0;row<lines.length;row++)ctx.fillText(lines[row],anchor,zone.y+row*lineHeight,zone.width);ctx.restore()}
function drawEventDivider(ctx,divider,theme,mode){if(!divider)return;ctx.save();ctx.strokeStyle=theme.colors.gold;ctx.globalAlpha=.58;ctx.lineWidth=1;if(mode==='split'){ctx.beginPath();ctx.moveTo(divider.x,divider.top);ctx.lineTo(divider.x,divider.bottom);ctx.stroke()}else{ctx.beginPath();ctx.moveTo(divider.x-70,divider.top);ctx.lineTo(divider.x+70,divider.bottom);ctx.stroke()}ctx.fillStyle=theme.colors.lotus;ctx.beginPath();ctx.arc(divider.x,(divider.top+divider.bottom)/2,3.5,0,Math.PI*2);ctx.fill();ctx.restore()}
function timeOfDay(value){let hour=Number(String(value||'11:30').split(':')[0]);return hour<12?'Buổi trưa':hour<18?'Buổi chiều':'Buổi tối'}
